import Phaser from 'phaser';

export class EndScene extends Phaser.Scene {
    constructor() {
        super({key: 'EndScene'});
        this.endImage = null;
        this.spaceKey = null;
        this.finalScore = 0;
    }

    init(data) {
        // Store the final score from the game scene
        this.finalScore = data && data.score ? data.score : 0;
    }

    create() {
        // Create end game image
        this.endImage = this.add.image(
            this.cameras.main.width / 2,
            this.cameras.main.height / 2,
            'endgame'
        );
        this.endImage.setOrigin(0.5);
        this.endImage.setScale(0.16); // Set to 16% of original size

        // Set up the space key to restart the game
        this.spaceKey = this.input.keyboard.addKey(Phaser.Input.Keyboard.KeyCodes.SPACE);

        // Add text instructions to restart
        const instructionText = this.add.text(
            this.cameras.main.width / 2,
            this.cameras.main.height - 50,
            'Press "START" to continue',
            {
                fontSize: '24px',
                color: '#FFFFFF'
            }
        );
        instructionText.setOrigin(0.5);
    }

    update() {
        // Check if space key is pressed to restart the game
        if (Phaser.Input.Keyboard.JustDown(this.spaceKey)) {
            this.scene.start('StartScene');
        }
    }
}
