// Function to initialize or get the game configuration from localStorage
export function initializeGameConfig() {
    // Try to get the configuration from localStorage
    const storedConfig = localStorage.getItem('gameConfig');

    if (storedConfig) {
        try {
            // Parse the stored configuration
            const parsedConfig = JSON.parse(storedConfig);
            return parsedConfig;
        } catch (error) {
            console.error('Error parsing stored game configuration:', error);
            // If there's an error, save and return the default configuration
            localStorage.setItem('gameConfig', JSON.stringify(defaultGameConfig));
            return defaultGameConfig;
        }
    } else {
        // If no configuration exists, save and return the default configuration
        localStorage.setItem('gameConfig', JSON.stringify(defaultGameConfig));
        return defaultGameConfig;
    }
}

// Get the game configuration
export const gameConfig = initializeGameConfig();