import Phaser from 'phaser';
import {gameConfig} from '../config';


export class GameScene extends Phaser.Scene {

    player;
    playerHealth = 10;
    bulletRate = 1;
    upgraded = false;

    // Game objects
    cursors;
    bullets;
    enemies;
    upgradeBox;

    // UI elements
    healthBar;
    scoreBar;

    // Game state
    lastFired = 0;
    score = 0;      // Actual score as float (fractional)
    displayScore = 0; // Display score (rounded down)
    gameTimer = 0;
    countdownTime = 70; // Countdown from 70 seconds
    spawnTimer = 0;
    gameStartTime;
    gameEnded = false;
    hardEnemySpawnTimer = 0;


    gameTimerEvent;
    bulletTimerEvent;
    timerText;

    constructor() {
        super({key: 'GameScene'});


    }


    create() {
        // Reset all game state values on scene creation
        this.gameTimer = 0;
        this.spawnTimer = 0;
        this.hardEnemySpawnTimer = 0;
        this.score = 0;
        this.playerHealth = gameConfig.player.health;
        this.bulletRate = gameConfig.player.bulletRate;
        this.upgraded = false;
        this.gameEnded = false;
        this.gameTimerEvent = null;
        this.bulletTimerEvent = null;

        // First, safely remove any existing groups
        if (this.bullets && typeof this.bullets.destroy === 'function') {
            this.bullets.destroy();
        }

        if (this.enemies && typeof this.enemies.destroy === 'function') {
            this.enemies.destroy();
        }

        // Create new bullet group
        this.bullets = this.physics.add.group({
            classType: Phaser.Physics.Arcade.Sprite,
            maxSize: 30,
            runChildUpdate: true
        });

        // Create new enemy group
        this.enemies = this.physics.add.group({
            classType: Phaser.Physics.Arcade.Sprite
        });

        console.log("Physics groups created");

        console.log("Game reset - starting with clean state");

        // Add the background
        const background = this.add.image(455, 455, 'background');
        background.setDisplaySize(910, 910);

        // Create the player using smallhospital initially (will upgrade to hospital later)
        this.player = this.physics.add.sprite(455, 850, 'smallhospital');
        this.player.setScale(0.09); // Set player to 9% of original size
        this.player.setCollideWorldBounds(true);

        // Set up cursor keys for player control
        this.cursors = this.input.keyboard.createCursorKeys();

        // Create bullet group
        this.bullets = this.physics.add.group({
            classType: Phaser.Physics.Arcade.Sprite,
            maxSize: 30,
            runChildUpdate: true
        });

        // Create enemy group
        this.enemies = this.physics.add.group({
            classType: Phaser.Physics.Arcade.Sprite
        });

        // Set up health and score bars (moved to y=50 as requested)
        // Using hp10.png initially for full health
        this.healthBar = this.add.image(150, 50, 'hp10');
        this.healthBar.setScale(0.16); // Make health display 16% of original size

        // Position the score bar between the timer and right border (at y=55)
        this.scoreBar = this.add.image(700, 55, 's0');
        this.scoreBar.setScale(0.16); // Make it much smaller to fit better

        // Set up collisions
        this.physics.add.collider(
            this.bullets,
            this.enemies,
            this.bulletHitEnemy,
            undefined,
            this);

        this.physics.add.collider(
            this.player,
            this.enemies,
            this.playerHitEnemy,
            undefined,
            this);

        // Create bullet firing timer
        const bulletTimer = this.time.addEvent({
            delay: 1000 / this.bulletRate,
            callback: this.fireBullet,
            callbackScope: this,
            loop: true
        });

        // Create the countdown timer - centered position with digital-style font
        // Initialize with 60 seconds (countdown timer)
        this.timerText = this.add.text(455, 60, '60', {
            fontSize: '36px',
            fontFamily: 'monospace, Courier, Monaco', // Digital-style font
            color: '#FFFFFF',
            fontStyle: 'bold'
        });
        this.timerText.setOrigin(0.5);

        // Add stroke and shadow to make numbers clearer
        this.timerText.setStroke('#000000', 4);
        this.timerText.setShadow(2, 2, '#000000', 2, true, true);

        // Initialize countdown timer value
        this.countdownTime = 60; // Set directly to 60 seconds

        // Setup bullet firing system first
        this.setupBulletFiring();

        // Then setup game timer
        this.setupGameTimer();
    }

    // Setup bullet firing timer
    setupBulletFiring() {
        // Clear any existing bullet timer
        if (this.bulletTimerEvent) {
            this.bulletTimerEvent.remove();
            this.bulletTimerEvent = null;
        }

        // Create a new bullet timer
        this.bulletTimerEvent = this.time.addEvent({
            delay: 1000 / this.bulletRate,
            callback: this.fireBullet,
            callbackScope: this,
            loop: true
        });

        console.log(`Bullet firing set up: ${this.bulletRate} per second`);
    }

    // Setup the game timer that handles game progression
    setupGameTimer() {
        // Clear any existing game timer
        if (this.gameTimerEvent) {
            this.gameTimerEvent.remove();
            this.gameTimerEvent = null;
        }

        // Create a reliable game timer with countdown from 60 seconds
        this.gameTimerEvent = this.time.addEvent({
            delay: 1000,
            callback: () => {
                if (this.gameEnded) return;

                // Increment the game timer (for internal tracking)
                this.gameTimer += 1;

                // Decrement the countdown timer
                this.countdownTime -= 1;
                console.log("Game timer:", this.gameTimer, "Countdown:", this.countdownTime);

                // Update timer display as a simple countdown
                this.timerText.setText(this.countdownTime.toString());

                // Handle events at specific times
                this.processGameEvents(this.gameTimer);

                // Force end the game after exactly 60 seconds (when countdown reaches 0)
                if (this.countdownTime <= 0) {
                    console.log("Game ending at 60 seconds");
                    this.gameEnded = true;
                    this.scene.start('EndScene', {score: Math.floor(this.score)});
                }
            },
            callbackScope: this,
            loop: true
        });
    }

    // Process game events at specific timer values
    processGameEvents(currentTime) {
        // Check if upgrade box needs to be spawned
        if (currentTime === 27 && !this.upgraded) {
            this.spawnUpgradeBox();
        }

        // No enemy spawning after 52 seconds
        if (currentTime > 52) {
            return;
        }

        // Special waves at specific times
        if (currentTime === 31) {
            // Special wave at 31 seconds
            console.log("Spawning wave at 31s - 7 normal enemies");
            for (let i = 0; i < 7; i++) {
                this.spawnNormalEnemy();
            }
        } else if (currentTime === 51) {
            // Special wave at 51 seconds
            console.log("Spawning wave at 51s - 5 normal + 2 hard enemies");
            for (let i = 0; i < 5; i++) {
                this.spawnNormalEnemy();
            }
            for (let i = 0; i < 2; i++) {
                this.spawnHardEnemy();
            }
        } else if (currentTime === 52) {
            // Special wave at 52 seconds
            console.log("Spawning wave at 52s - 7 normal + 2 hard enemies");
            for (let i = 0; i < 7; i++) {
                this.spawnNormalEnemy();
            }
            for (let i = 0; i < 2; i++) {
                this.spawnHardEnemy();
            }
        }
            /* Final wave at 53 seconds has been removed
            else if (currentTime === 53) {
              console.log("Spawning final wave at 53s - 8 normal + 3 hard enemies");
              for (let i = 0; i < 8; i++) {
                this.spawnNormalEnemy();
              }
              for (let i = 0; i < 3; i++) {
                this.spawnHardEnemy();
              }
            }
            */
        // First 15 seconds (0-15s): 1 Normal enemy per second
        else if (currentTime > 0 && currentTime <= 15) {
            console.log(`Spawning at ${currentTime}s: 1 normal enemy`);
            this.spawnNormalEnemy();
        }
        // Between 15-23 seconds: 2 Normal enemies per second
        else if (currentTime > 15 && currentTime <= 23) {
            console.log(`Spawning at ${currentTime}s: 2 normal enemies`);
            for (let i = 0; i < 2; i++) {
                this.spawnNormalEnemy();
            }
        }
        // Between 23-30 seconds: 3 Normal enemies per second
        else if (currentTime > 23 && currentTime <= 30) {
            console.log(`Spawning at ${currentTime}s: 3 normal enemies`);
            for (let i = 0; i < 3; i++) {
                this.spawnNormalEnemy();
            }
        }
        // Between 32-40 seconds: Enhanced spawn pattern (8 Normal enemies per second)
        else if (currentTime >= 32 && currentTime <= 40) {
            console.log(`Enhanced spawn at ${currentTime}s: 8 enemies (6 black, 1 yellow, 1 red)`);

            // Spawn 6 black enemies
            for (let i = 0; i < 6; i++) {
                // Force black enemies by setting specific type (within proper game boundaries 100-810)
                const x = Phaser.Math.Between(100, 810);
                const blackType = Phaser.Math.Between(1, 2);
                const enemy = this.enemies.create(x, 56, `black${blackType}`);
                enemy.setActive(true);
                enemy.setScale(0.1); // Ensure enemy is always 10% of original size
                enemy.setVelocityY(100);
                enemy.health = gameConfig.enemies.normal.black.health;
                enemy.value = 1;
                enemy.type = 'normal';

                // Add update listener to ensure enemy always moves down
                this.time.addEvent({
                    delay: 100,
                    callback: () => {
                        if (enemy.active) {
                            enemy.setVelocityY(100);
                        }
                    },
                    loop: true
                });
            }

            // Spawn 1 yellow enemy (within proper game boundaries 100-810)
            const yellowX = Phaser.Math.Between(100, 810);
            const yellowEnemy = this.enemies.create(yellowX, 56, 'yellow');
            yellowEnemy.setScale(0.1); // Ensure enemy is always 10% of original size
            yellowEnemy.setVelocityY(100);
            yellowEnemy.health = gameConfig.enemies.normal.yellow.health;
            yellowEnemy.value = 2;
            yellowEnemy.type = 'normal';
            this.time.addEvent({
                delay: 100,
                callback: () => {
                    if (yellowEnemy.active) {
                        yellowEnemy.setVelocityY(100);
                    }
                },
                loop: true
            });

            // Spawn 1 red enemy (within proper game boundaries 100-810)
            const redX = Phaser.Math.Between(100, 810);
            const redEnemy = this.enemies.create(redX, 56, 'red');
            redEnemy.setScale(0.1); // Ensure enemy is always 10% of original size
            redEnemy.setVelocityY(100);
            redEnemy.health = gameConfig.enemies.normal.red.health;
            redEnemy.value = 3;
            redEnemy.type = 'normal';
            this.time.addEvent({
                delay: 100,
                callback: () => {
                    if (redEnemy.active) {
                        redEnemy.setVelocityY(100);
                    }
                },
                loop: true
            });
        }
        // From 41-45s: 1 hard enemy + 2 normal enemies per second
        else if (currentTime >= 41 && currentTime <= 45) {
            console.log(`Spawning at ${currentTime}s: 1 hard + 2 normal enemies`);
            // Spawn 1 hard enemy
            this.spawnHardEnemy();

            // Spawn 2 normal enemies
            for (let i = 0; i < 2; i++) {
                this.spawnNormalEnemy();
            }
        }
        // From 46-50s: 1 hard enemy + 5 normal enemies per second
        else if (currentTime >= 46 && currentTime <= 50) {
            console.log(`Spawning at ${currentTime}s: 1 hard + 5 normal enemies`);
            // Spawn 1 hard enemy
            this.spawnHardEnemy();

            // Spawn 5 normal enemies
            for (let i = 0; i < 5; i++) {
                this.spawnNormalEnemy();
            }
        }
        // This section is no longer used since we stop spawning after 53s
        // Left here for reference only
        /*
        else if (currentTime >= 54 && currentTime <= 60) {
          console.log(`Final phase at ${currentTime}s: 3 normal + 1 hard enemy`);
          // Spawn 1 hard enemy
          this.spawnHardEnemy();

          // Spawn 3 normal enemies
          for (let i = 0; i < 3; i++) {
            this.spawnNormalEnemy();
          }
        }
        */
    }

    update(time, delta) {
        // Skip updates if game has ended
        if (this.gameEnded) return;

        // Force end the game at 60 seconds (as a backup check)
        if (this.gameTimer >= 60 && !this.gameEnded) {
            console.log("Forcing game end at 60 seconds");
            this.gameEnded = true;
            this.scene.start('EndScene', {score: Math.floor(this.score)});
            return;
        }

        // Control player movement with new game boundaries (100-810)
        if (this.cursors.left.isDown) {
            this.player.setVelocityX(-gameConfig.player.speed);
        } else if (this.cursors.right.isDown) {
            this.player.setVelocityX(gameConfig.player.speed);
        } else {
            this.player.setVelocityX(0);
        }

        // Always keep player's vertical position fixed at 850
        this.player.setVelocityY(0);
        this.player.y = 850;

        // Enforce game boundaries (100-810) for player
        if (this.player.x < 100) {
            this.player.x = 100;
        } else if (this.player.x > 810) {
            this.player.x = 810;
        }

        // Handle enemies that reach the bottom of the screen
        this.handleEnemiesOutOfBounds();

        // Check all bullets and destroy them if they reach the score area (y <= 50)
        // or go beyond the game's horizontal boundaries (100-810)
        this.bullets.getChildren().forEach((bulletObj) => {
            if (bulletObj.active && 'y' in bulletObj) {
                const bullet = bulletObj;
                if (bullet.y <= 50 ||
                    bullet.x < 100 ||
                    bullet.x > 810) {
                    bullet.destroy();
                }
            }
        });
    }

    fireBullet() {
        // Don't fire if game has ended
        if (this.gameEnded) return;

        // If upgrade is active, fire 5 bullets in a fan pattern
        if (this.upgraded) {
            // Force firing all 5 angles consistently, regardless of player movement

            // Get current player position for bullet spawn
            const playerX = this.player.x;
            const playerY = this.player.y;

            // Create all 5 bullets with specified angles in a single frame
            // This ensures all bullets are fired even during rapid movement
            const angles = [0, -15, 15, -30, 30];

            // Fire all bullets at once from exact player position
            angles.forEach(angle => {
                this.createBulletAtPosition(playerX, playerY - 20, angle);
            });

            // Log for debugging
            console.log("Firing all 5 bullet angles");
        } else {
            // Fire a single bullet upward
            this.createBullet(0);
        }
    }

    // Additional method to create bullets at specific positions
    createBulletAtPosition(x, y, angle) {
        // Get a bullet from the pool at the exact specified position
        const bullet = this.bullets.get(x, y, 'bullet');

        if (bullet) {
            bullet.setActive(true);
            bullet.setVisible(true);
            bullet.setScale(0.065); // Make bullets 6.5% of original size
            bullet.damage = 1; // Each bullet deals 1 damage

            // Calculate velocity based on angle
            const radian = Phaser.Math.DegToRad(angle - 90); // -90 because we want the baseline to be upward

            // Speed should be dependent on whether player is upgraded or not
            // Non-upgraded bullets should be 60% of the speed of upgraded bullets
            const baseSpeed = 1200; // Base speed for upgraded bullets
            const speed = this.upgraded ? baseSpeed : (baseSpeed * 0.6); // Non-upgraded bullets are 60% slower

            const velocityX = Math.cos(radian) * speed;
            const velocityY = Math.sin(radian) * speed;

            // Set bullet velocity
            bullet.setVelocity(velocityX, velocityY);

            // Set bullet to independent physics so it won't be affected by player movement
            if (bullet.body) {
                // Ensure bullets move independently by setting immovable property
                bullet.body.immovable = true;
            }

            // Store score area boundary data for reference in update loop
            bullet.setData('scoreAreaBoundary', 50); // y=50 is where score display is

            // Bullets should be cleaned up if they don't hit anything
            // Use a longer timeout to ensure bullets have time to reach enemies
            this.time.delayedCall(3000, () => {
                if (bullet && bullet.active) {
                    // Only destroy the bullet if it's still active after timeout
                    bullet.destroy();
                }
            });
        }
    }

    createBullet(angle) {
        // Get a bullet from the pool
        const bullet = this.bullets.get(
            this.player.x,
            this.player.y - 20,
            'bullet'
        );

        if (bullet) {
            bullet.setActive(true);
            bullet.setVisible(true);
            bullet.setScale(0.065); // Make bullets 6.5% of original size (per user request)
            bullet.damage = 1; // Each bullet deals 1 damage

            // Calculate velocity based on angle
            const radian = Phaser.Math.DegToRad(angle - 90); // -90 because we want the baseline to be upward

            // Speed should be dependent on whether player is upgraded or not
            // Non-upgraded bullets should be 60% of the speed of upgraded bullets
            const baseSpeed = 1200; // Base speed for upgraded bullets
            const speed = this.upgraded ? baseSpeed : (baseSpeed * 0.6); // Non-upgraded bullets are 60% slower

            const velocityX = Math.cos(radian) * speed;
            const velocityY = Math.sin(radian) * speed;

            // Set bullet velocity
            bullet.setVelocity(velocityX, velocityY);

            // Set bullet to independent physics so it won't be affected by player movement
            if (bullet.body) {
                // Ensure bullets move independently by setting immovable property
                bullet.body.immovable = true;
            }

            // Make sure bullets are destroyed when they go off screen
            bullet.setData('created', Date.now());

            // Bullets should be cleaned up if they don't hit anything
            // Use a longer timeout (3000ms instead of 2000ms) to ensure bullets have time to reach enemies
            this.time.delayedCall(3000, () => {
                if (bullet && bullet.active) {
                    // Only destroy the bullet if it's still active after 3 seconds
                    bullet.destroy();
                }
            });
        }
    }

    handleEnemySpawning() {
        // Get current game time
        const currentTime = this.gameTimer;

        // Check if upgrade box needs to be spawned (at 27 seconds if player doesn't have upgrade)
        if (currentTime === 27 && !this.upgraded) {
            this.spawnUpgradeBox();
        }

        // STOP spawning enemies after 60 seconds
        if (currentTime > 60) {
            return;
        }

        // Special wave at 30 seconds: 7 normal enemies
        if (currentTime === 30) {
            console.log("Spawning wave at 30s - 7 normal enemies");
            for (let i = 0; i < 7; i++) {
                this.spawnNormalEnemy();
            }
        }
        // Special wave at 57 seconds: 6 normal + 2 hard enemies
        else if (currentTime === 57) {
            console.log("Spawning wave at 57s - 6 normal + 2 hard enemies");
            for (let i = 0; i < 6; i++) {
                this.spawnNormalEnemy();
            }
            for (let i = 0; i < 2; i++) {
                this.spawnHardEnemy();
            }
        }
        // Special wave at 58 seconds: 7 normal + 2 hard enemies
        else if (currentTime === 58) {
            console.log("Spawning wave at 58s - 7 normal + 2 hard enemies");
            for (let i = 0; i < 7; i++) {
                this.spawnNormalEnemy();
            }
            for (let i = 0; i < 2; i++) {
                this.spawnHardEnemy();
            }
        }
        // Final wave at 60 seconds: 8 normal + 3 hard enemies
        else if (currentTime === 60) {
            console.log("Spawning final wave at 60s - 8 normal + 3 hard enemies");
            for (let i = 0; i < 8; i++) {
                this.spawnNormalEnemy();
            }
            for (let i = 0; i < 3; i++) {
                this.spawnHardEnemy();
            }
        }
        // Regular enemy spawning based on time period
        else {
            // First 30 seconds: normal enemies with a consistent, slower spawn rate
            if (currentTime < 30) {
                // Fixed spawn delay of 1000ms (1 enemy/second)
                const spawnDelay = 1000;

                // Increment spawn timer
                this.spawnTimer += this.game.loop.delta;

                // Check if it's time to spawn a new enemy
                if (this.spawnTimer >= spawnDelay) {
                    this.spawnTimer = 0;
                    this.spawnNormalEnemy();
                }
            }

            // Between 45-56 seconds: spawn both normal and hard enemies
            else if (currentTime >= 45 && currentTime < 57) {
                // Spawn every 2 seconds
                const spawnDelay = 2000;
                this.spawnTimer += this.game.loop.delta;

                if (this.spawnTimer >= spawnDelay) {
                    this.spawnTimer = 0;

                    // Determine enemy counts based on time
                    // Later in the period, increase from 1+4 to 2+5
                    const hardCount = currentTime >= 51 ? 2 : 1;
                    const normalCount = currentTime >= 51 ? 5 : 4;

                    // Spawn hard enemies
                    for (let i = 0; i < hardCount; i++) {
                        this.spawnHardEnemy();
                    }

                    // Spawn normal enemies
                    for (let i = 0; i < normalCount; i++) {
                        this.spawnNormalEnemy();
                    }
                }
            }
        }
    }

    spawnNormalEnemy() {
        // Decide which type of normal enemy to spawn based on probabilities
        const enemyType = this.getRandomNormalEnemyType();

        // Get random x position (within the proper game boundaries 100-810)
        const x = Phaser.Math.Between(100, 810);

        // Start enemies below the score display (below y=56)
        const startY = 56;

        console.log(`Spawning normal enemy: ${enemyType.image} with health: ${enemyType.health}`);

        // Create the enemy
        const enemy = this.enemies.create(x, startY, enemyType.image);
        enemy.setActive(true);
        enemy.setScale(0.1); // Make enemies 10% of original size

        // Set enemy properties
        enemy.setVelocityY(100); // Move downward at 100 pixels/second
        enemy.health = enemyType.health;
        enemy.value = enemyType.value;
        enemy.type = 'normal';

        // Store original speed so it doesn't get pushed when hit by bullets
        enemy.setData('originalSpeed', 100);

        // Add update listener to ensure enemy always moves down at consistent speed
        // and stays within game boundaries
        this.time.addEvent({
            delay: 100,
            callback: () => {
                if (enemy.active) {
                    // Always maintain the same downward movement - prevents "pushing" when hit
                    enemy.setVelocityY(100);

                    // Ensure enemy stays within proper game boundaries (100-810)
                    if (enemy.x < 100) {
                        enemy.x = 100;
                        // Stop horizontal movement once it hits the border
                        enemy.setVelocityX(0);
                    }
                    if (enemy.x > 810) {
                        enemy.x = 810;
                        // Stop horizontal movement once it hits the border
                        enemy.setVelocityX(0);
                    }
                }
            },
            loop: true
        });
    }

    spawnHardEnemy() {
        // Decide which type of hard enemy to spawn
        const enemyType = this.getRandomHardEnemyType();

        // Get random x position (within proper game boundaries 100-810)
        const x = Phaser.Math.Between(100, 810);

        // Start enemies below the score display (below y=56)
        const startY = 56;

        console.log(`Spawning hard enemy: ${enemyType.image} with health: ${enemyType.health}`);

        // Create the enemy
        const enemy = this.enemies.create(x, startY, enemyType.image);
        enemy.setActive(true);
        enemy.setScale(0.1); // Make hard enemies 10% of original size

        // Set enemy properties
        enemy.setVelocityY(70); // Hard enemies move slightly slower
        enemy.health = enemyType.health;
        enemy.value = enemyType.value;
        enemy.type = 'hard';

        // Store original speed so it doesn't get pushed when hit by bullets
        enemy.setData('originalSpeed', 70);

        // Add update listener to ensure enemy always moves down and stays within game boundaries
        this.time.addEvent({
            delay: 100,
            callback: () => {
                if (enemy.active) {
                    // Always maintain the same downward movement - prevents "pushing" when hit
                    enemy.setVelocityY(70);

                    // Ensure enemy stays within proper game boundaries (100-810)
                    if (enemy.x < 100) {
                        enemy.x = 100;
                        // Stop horizontal movement once it hits the border
                        enemy.setVelocityX(0);
                    }
                    if (enemy.x > 810) {
                        enemy.x = 810;
                        // Stop horizontal movement once it hits the border
                        enemy.setVelocityX(0);
                    }
                }
            },
            loop: true
        });
    }

    spawnUpgradeBox() {
        // First check if there's already an upgrade box - only allow one at a time
        if (this.upgradeBox && this.upgradeBox.active) {
            return;
        }

        // Get random x position (within proper game boundaries 100-810)
        const x = Phaser.Math.Between(100, 810);

        // Start upgrade box below the score display (around 40-50px down)
        const startY = 50;

        // Create the upgrade box
        this.upgradeBox = this.physics.add.sprite(x, startY, 'upgradebox');
        this.upgradeBox.setScale(0.12); // Make the upgrade box 12% of original size
        this.upgradeBox.setVelocityY(150); // 1.5x faster than enemies (enemies move at 100)

        console.log("Upgrade box spawned at position:", x);

        // Add update listener to ensure upgrade box stays within game boundaries
        this.time.addEvent({
            delay: 100,
            callback: () => {
                if (this.upgradeBox && this.upgradeBox.active) {
                    // Ensure upgrade box stays within proper game boundaries (100-810)
                    if (this.upgradeBox.x < 100) {
                        this.upgradeBox.x = 100;
                        // Stop horizontal movement once it hits the border
                        this.upgradeBox.setVelocityX(0);
                    }
                    if (this.upgradeBox.x > 810) {
                        this.upgradeBox.x = 810;
                        // Stop horizontal movement once it hits the border
                        this.upgradeBox.setVelocityX(0);
                    }

                    // Maintain consistent downward velocity
                    this.upgradeBox.setVelocityY(150);
                }
            },
            loop: true
        });

        // Set up collision with the player
        this.physics.add.overlap(
            this.player,
            this.upgradeBox,
            this.playerCollectUpgrade,
            undefined,
            this);
    }

    getRandomNormalEnemyType() {
        // Random number to determine enemy type
        const rand = Phaser.Math.Between(1, 100);

        // 90% chance for black, 5% yellow, 5% red
        if (rand <= 90) {
            // For black enemies, randomly choose between black1 and black2
            const blackType = Phaser.Math.Between(1, 2);
            return {
                image: `black${blackType}`,
                health: gameConfig.enemies.normal.black.health, // Set to 2 in config
                value: 1
            };
        } else if (rand <= 95) {
            return {
                image: 'yellow',
                health: gameConfig.enemies.normal.yellow.health,
                value: 2
            };
        } else {
            return {
                image: 'red',
                health: gameConfig.enemies.normal.red.health,
                value: 3  // Increased value for red enemies
            };
        }
    }

    getRandomHardEnemyType() {
        // Random number to determine hard enemy type
        const rand = Phaser.Math.Between(1, 100);

        // 50% chance for black grouped, 50% for mixed grouped
        if (rand <= 50) {
            return {
                image: 'mixedblack',
                health: gameConfig.enemies.hard.blackGrouped.health,
                value: 5
            };
        } else {
            // For mixed grouped, randomly choose between mixed1 and mixed2
            const mixedType = Phaser.Math.Between(1, 2);
            return {
                image: `mixed${mixedType}`,
                health: gameConfig.enemies.hard.mixedGrouped.health,
                value: 8
            };
        }
    }

    bulletHitEnemy(bullet, enemy) {
        // Only process if the bullet is active (prevents one bullet from hitting multiple enemies)

        if (!bullet.active || !enemy.active) {
            return;
        }

        // Save enemy's current x position before any collision processing
        const originalX = enemy.x;

        // Immediately make bullet inactive AND destroy it to ensure a smaller hit box
        // This prevents one bullet from hitting multiple enemies
        bullet.setActive(false);
        bullet.destroy();

        // Reduce enemy health by bullet damage (each bullet does 1 damage)
        enemy.health -= bullet.damage;

        // IMPORTANT: Preserve enemy's exact horizontal position regardless of bullet hit direction
        // This ensures sideway bullets don't cause any horizontal movement
        enemy.x = originalX;

        // Keep original vertical speed
        const originalSpeed = enemy.getData('originalSpeed') || (enemy.type === 'hard' ? 70 : 100);
        enemy.setVelocity(0, originalSpeed);

        // If enemy has no health left, destroy it and add score
        if (enemy.health <= 0) {
            enemy.destroy();

            // Add to floating score based on enemy type
            // Normal enemies worth 0.2 points, hard enemies worth 1 point
            // Use floating point for the actual score, but display rounded down integer
            const pointValue = enemy.type === 'hard' ? 1.0 : 0.2;
            this.score = Math.min(20, this.score + pointValue);

            // Update the display score (floor the actual score)
            this.displayScore = Math.floor(this.score);

            // Update score display with the rounded down value
            this.updateScoreDisplay();
        }

        // Console log for debugging
        console.log(`Enemy hit! Remaining health: ${enemy.health}`);
    }

    playerHitEnemy(_player, enemy) {
        // Destroy the enemy
        enemy.destroy();

        // Reduce player health
        this.playerHealth = Math.max(0, this.playerHealth - 1);

        // Update health display
        this.updateHealthDisplay();
    }

    playerCollectUpgrade(_player, upgradeBox) {
        // Remove the upgrade box
        upgradeBox.destroy();

        // Apply the upgrade (5 bullets in a fan pattern, 5 per second EACH angle - total 25 bullets per second)
        this.upgraded = true;

        // Change the fire rate to 5 bullets per second FOR EACH ANGLE (5 angles x 5 bullets/sec = 25 total bullets per second)
        this.bulletRate = 5;

        console.log("WEAPON UPGRADED! Now firing 5 bullets at 5 bullets/second per angle (25 total)!");

        // Display the level up splash image in the center of the screen for 1.5 seconds
        const levelUpImage = this.add.image(455, 455, 'levelup');
        levelUpImage.setScale(0.3); // Display at 30% of original size
        levelUpImage.setDepth(1000); // Ensure it appears on top of everything

        // Make it fade in and out for a nice effect
        levelUpImage.setAlpha(0); // Start transparent

        // Fade in
        this.tweens.add({
            targets: levelUpImage,
            alpha: 1,
            duration: 300,
            ease: 'Linear',
            onComplete: () => {
                // Hold at full opacity, then fade out
                this.time.delayedCall(900, () => {
                    this.tweens.add({
                        targets: levelUpImage,
                        alpha: 0,
                        duration: 300,
                        ease: 'Linear',
                        onComplete: () => {
                            levelUpImage.destroy();
                        }
                    });
                });
            }
        });

        // Change player sprite to upgraded hospital image
        this.player.setTexture('hospital');
        this.player.setScale(0.09); // Maintain same scale as smallhospital

        // Stop the old bullet timer
        if (this.bulletTimerEvent) {
            this.bulletTimerEvent.remove();
        }

        // Create a new bullet timer with upgraded rate
        this.bulletTimerEvent = this.time.addEvent({
            delay: 1000 / this.bulletRate,
            callback: this.fireBullet,
            callbackScope: this,
            loop: true
        });

        // Set up health regeneration - add 2 HP every 3 seconds after upgrade
        this.time.addEvent({
            delay: 3000, // 3 seconds
            callback: this.regenerateHealth,
            callbackScope: this,
            loop: true
        });

        console.log("Weapon upgraded: 5 bullets/second in 5 angles and health regeneration activated");
    }

    regenerateHealth() {
        // Only regenerate health if player is still alive and has been upgraded
        if (this.upgraded && this.playerHealth < 10 && !this.gameEnded) {
            // Add 2 HP (capped at max health of 10) - changed from 1 to 2 HP per user request
            this.playerHealth = Math.min(10, this.playerHealth + 2);
            console.log(`Health regenerated! Current health: ${this.playerHealth}`);

            // Update the health display
            this.updateHealthDisplay();
        }
    }

    handleEnemiesOutOfBounds() {
        // Check all active enemies
        this.enemies.getChildren().forEach((enemy) => {
            const e = enemy;

            // If enemy has moved past the bottom of the screen
            if (e.y > 860) {
                // Reduce player health
                this.playerHealth = Math.max(0, this.playerHealth - 1);

                // Update health display
                this.updateHealthDisplay();

                // Remove the enemy
                e.destroy();
            }
        });

        // Check if upgrade box is out of bounds
        if (this.upgradeBox && this.upgradeBox.active && this.upgradeBox.y > 860) {
            // If upgrade box reaches the bottom, destroy it and prepare to spawn a new one
            this.upgradeBox.destroy();

            // Allow a new upgrade box to spawn
            if (!this.upgraded) {
                // Schedule a new upgrade box to spawn in 5 seconds
                this.time.delayedCall(5000, () => {
                    if (!this.upgraded && !this.gameEnded) {
                        this.spawnUpgradeBox();
                    }
                });
            }
        }
    }

    updateHealthDisplay() {
        // Update the health bar display based on current health
        // Ensure health is clamped between 0 and 10
        const health = Phaser.Math.Clamp(this.playerHealth, 0, 10);

        // Use the correct health image based on current health (hp0.png to hp10.png)
        this.healthBar.setTexture(`hp${health}`);

        // Keep scale consistent at 16%
        this.healthBar.setScale(0.16);

        console.log(`Health updated to: ${health}, using image: hp${health}`);
    }

    updateScoreDisplay() {
        // Update the score bar image based on displayScore (rounded down integer)
        // Use the floor of actual score for display, and cap at 20
        const displayScore = Math.min(Math.floor(this.score), 20);
        this.displayScore = displayScore; // Update the display score property

        // Use the s0-s20 PNG images from the scores folder
        // Make sure to always show the correct score image, even for score 0
        this.scoreBar.setTexture(`s${displayScore}`);
        this.scoreBar.setScale(0.16); // Ensure score display is 16% of original size
        this.scoreBar.setVisible(true); // Always keep the score visible

        console.log(`Score updated to: ${displayScore}, using image: s${displayScore}`);
        console.log(`Actual floating score: ${this.score.toFixed(1)}`); // Show actual fractional score in logs
    }
}
