import Phaser from 'phaser';

export class StartScene extends Phaser.Scene {
    constructor() {
        super({key: 'StartScene'});
        this.startImage = null;
        this.spaceKey = null;
        this.countdownText = null;
        this.countdown = 3;
        this.countdownStarted = false;
    }

    preload() {
        // Preload all game assets
        this.load.image('startgame', '/assets/startgame.png');  // Use new PNG start screen
        this.load.image('background', '/assets/background.png'); // Use PNG background
        this.load.image('endgame', '/assets/endgame.png');  // Use new PNG end screen

        // Player sprites
        this.load.image('smallhospital', '/assets/smallhospital.png');
        this.load.image('hospital', '/assets/hospital.png');

        // Enemies - Using new PNG images
        this.load.image('black1', '/assets/black1.png');
        this.load.image('black2', '/assets/black2.png');
        this.load.image('yellow', '/assets/yellow.png');
        this.load.image('red', '/assets/red.png');
        this.load.image('mixedblack', '/assets/mixedblack.png');
        this.load.image('mixed1', '/assets/mixed1.png');
        this.load.image('mixed2', '/assets/mixed2.png');

        // Load the score images (s0.png to s20.png)
        for (let i = 0; i <= 20; i++) {
            this.load.image(`s${i}`, `/assets/scores/s${i}.png`);
        }

        // Other game elements
        this.load.image('bullet', '/assets/bullet_new.png'); // Use the new bullet image
        this.load.image('upgradebox', '/assets/upgradebox.png');  // Use PNG upgrade box
        this.load.image('levelup', '/assets/levelup.png');  // Level up splash image

        // Health images (hp0.png to hp10.png)
        for (let i = 0; i <= 10; i++) {
            this.load.image(`hp${i}`, `/assets/hp${i}.png`);
        }

        // We're using PNG score images now, no need to load SVGs
    }

    create() {
        // Reset the countdownStarted flag to ensure we can always start a new game
        this.countdownStarted = false;

        // Create start game image
        this.startImage = this.add.image(
            this.cameras.main.width / 2,
            this.cameras.main.height / 2,
            'startgame'
        );
        this.startImage.setOrigin(0.5);
        this.startImage.setScale(0.16); // Set to 16% of original size

        // Create countdown text (hidden initially)
        this.countdownText = this.add.text(
            this.cameras.main.width / 2,
            this.cameras.main.height / 2,
            '',
            {
                fontSize: '64px',
                color: '#FFFFFF',
                fontStyle: 'bold'
            }
        );
        this.countdownText.setOrigin(0.5);
        this.countdownText.setVisible(false);

        // Set up the space key to start the game
        this.spaceKey = this.input.keyboard.addKey(Phaser.Input.Keyboard.KeyCodes.SPACE);

        // Add text instructions
        const instructionText = this.add.text(
            this.cameras.main.width / 2,
            this.cameras.main.height - 50,
            'Press "START" to begin',
            {
                fontSize: '24px',
                color: '#FFFFFF'
            }
        );
        instructionText.setOrigin(0.5);
    }

    update() {
        // Check if space key is pressed and countdown hasn't started
        if (Phaser.Input.Keyboard.JustDown(this.spaceKey) && !this.countdownStarted) {
            // Reset the countdown flag to ensure game can be restarted
            this.countdownStarted = false;
            this.startCountdown();
        }
    }

    startCountdown() {
        // Reset countdown value to 3 to ensure it always works properly when restarting
        this.countdown = 3;

        // Set flag to prevent multiple countdowns
        this.countdownStarted = true;

        // Hide the start image
        this.startImage.setVisible(false);

        // Show the countdown text
        this.countdownText.setVisible(true);
        this.countdownText.setText(`${this.countdown}`);

        console.log("Starting countdown from 3...");

        // Create a timer to update the countdown
        const countdownTimer = this.time.addEvent({
            delay: 1000,
            callback: () => {
                this.countdown--;

                if (this.countdown > 0) {
                    // Update the countdown text
                    this.countdownText.setText(`${this.countdown}`);
                    console.log(`Countdown: ${this.countdown}`);
                } else {
                    // When countdown reaches 0, start the game
                    console.log("Countdown complete, starting game");
                    this.scene.start('GameScene');
                }
            },
            callbackScope: this,
            repeat: 2
        });
    }
}